import{_ as l,o as r,c as e,ag as o}from"./chunks/framework.C9sp7nFj.js";const u=JSON.parse('{"title":"Skill、MCP、Rule 的异同","description":"","frontmatter":{},"headers":[],"relativePath":"AI/skill-vs-mcp.md","filePath":"AI/skill-vs-mcp.md"}'),d={name:"AI/skill-vs-mcp.md"};function i(s,t,a,n,g,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="skill、mcp、rule-的异同" tabindex="-1">Skill、MCP、Rule 的异同 <a class="header-anchor" href="#skill、mcp、rule-的异同" aria-label="Permalink to &quot;Skill、MCP、Rule 的异同&quot;">​</a></h1><p>四样东西经常堆在一个 Agent 产品里：<strong>Rule、AGENTS.md、Skill、MCP</strong>。前三样都是「给模型看的字」，MCP 是「给 Host 插的工具」。不要用「能不能跑命令 / 能不能看 git」来分 Skill 和 MCP，Skill 里的脚本照样能 <code>git diff</code>。</p><p>分篇说明：<a href="./skill.html">Skill</a>、<a href="./rule.html">Rule</a>、<a href="./agents-md.html">AGENTS.md</a>、<a href="./mcp.html">MCP</a>。Skill 怎么进上下文：<a href="./skill-how.html">生效原理</a>。</p><h2 id="相同点" tabindex="-1">相同点 <a class="header-anchor" href="#相同点" aria-label="Permalink to &quot;相同点&quot;">​</a></h2><ul><li>都是为了让 Agent <strong>少临时发挥</strong>：有约定、有手脚、有禁区</li><li>都可以进 git，变成团队资产</li><li>都可以和 Cursor、Claude Code 等 Host 一起用</li><li>Rule / AGENTS.md / Skill <strong>都没有独立进程</strong>，只是磁盘上的说明；MCP <strong>有进程</strong>（或远程服务）</li></ul><h2 id="不同点-一句话" tabindex="-1">不同点（一句话） <a class="header-anchor" href="#不同点-一句话" aria-label="Permalink to &quot;不同点（一句话）&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>人话</th><th>典型形态</th></tr></thead><tbody><tr><td><strong>AGENTS.md</strong></td><td>这个<strong>仓库</strong>怎么干活</td><td>根目录一份 Markdown</td></tr><tr><td><strong>Rule</strong></td><td>这些话<strong>尽量每次都遵守</strong>（或改某类文件时遵守）</td><td><code>.cursor/rules/*.mdc</code></td></tr><tr><td><strong>Skill</strong></td><td>做<strong>这一类任务</strong>时按这套步骤</td><td><code>SKILL.md</code> + 可选脚本</td></tr><tr><td><strong>MCP</strong></td><td>去<strong>连某个外部系统</strong></td><td>Server + 工具 schema</td></tr></tbody></table><p>加载成本也不一样：</p><table tabindex="0"><thead><tr><th></th><th>怎么进上下文</th><th>写长了会怎样</th></tr></thead><tbody><tr><td>Rule / AGENTS.md</td><td>常驻或按路径，<strong>全文进去</strong></td><td>每条消息都占窗口</td></tr><tr><td>Skill</td><td>先注入 <code>name</code> + <code>description</code>，对上了才读正文</td><td>没触发时几乎不占</td></tr><tr><td>MCP</td><td>工具列表给模型看；真正执行发生在 Server</td><td>工具太多会干扰选型，但不会把说明书全文塞进每一轮</td></tr></tbody></table><h2 id="用同一句话看该写哪" tabindex="-1">用同一句话看该写哪 <a class="header-anchor" href="#用同一句话看该写哪" aria-label="Permalink to &quot;用同一句话看该写哪&quot;">​</a></h2><p>用户说：「这个接口超时了，帮我查，按我们组的格式给结论。」</p><ul><li><strong>AGENTS.md</strong>：<code>pnpm test</code>、日志脚本在 <code>script/</code>、不要用 <code>rm</code>（仓库公约，跟这次超不超时无关也会用到）</li><li><strong>Rule</strong>：改监控配置时禁止提交密钥（短禁令，always 或 glob）</li><li><strong>Skill</strong>：收集时间/环境 → 查日志 → 定级 → 结论必须有影响面和止血（流程）</li><li><strong>MCP</strong>：Sentry <code>search_errors</code>（线上数据不在 git 里）</li></ul><p>只有 Skill：步骤清楚，但可能查不到线上错误。只有 MCP：能拉 JSON，结论像倒垃圾。只有 Rule：每条消息都带着「别提交密钥」，但没人告诉它排障怎么走。</p><p>代码侧再拆一次：</p><table tabindex="0"><thead><tr><th>你要的</th><th>写哪</th></tr></thead><tbody><tr><td>「本仓库用 pnpm，不要动 <code>dist/</code>」</td><td><strong>AGENTS.md</strong></td></tr><tr><td>「<code>*.scss</code> 禁止 flex gap」</td><td><strong>Rule</strong>（glob）</td></tr><tr><td>「review 意见必须分成必须修 / 建议改」</td><td><strong>Skill</strong></td></tr><tr><td>「看当前分支 <code>git diff</code>」</td><td><strong>Skill 脚本</strong>或直接让 Agent 跑 git，不必 MCP</td></tr><tr><td>「把意见发到 GitHub PR 上 / 查 org 的 Issue」</td><td><strong>MCP</strong>（或 <code>gh</code>）。这不是本地 git 对象</td></tr></tbody></table><h2 id="skill-和-mcp-容易糊的地方" tabindex="-1">Skill 和 MCP 容易糊的地方 <a class="header-anchor" href="#skill-和-mcp-容易糊的地方" aria-label="Permalink to &quot;Skill 和 MCP 容易糊的地方&quot;">​</a></h2><p>两边都能「做事」。本地 <code>git log</code> 放 Skill 的 <code>scripts/</code> 就够。GitHub MCP 也能列 commit。所以「看 git」<strong>不是</strong>分界。</p><p>改问：<strong>这是当前工作区的一条命令，还是要插在 Host 上、换仓库也能用的服务？</strong></p><ul><li>当前 clone 里有的 → Skill 脚本 / 终端</li><li>要登录态、跨项目、结构化入参（Sentry、GitHub 网站、内部 RPC）→ MCP</li><li>Skill 脚本 ≠ MCP：脚本跟这份 <code>SKILL.md</code> 走；MCP 跟某一个 Skill 解耦</li></ul><h2 id="和-rule-容易糊的地方" tabindex="-1">和 Rule 容易糊的地方 <a class="header-anchor" href="#和-rule-容易糊的地方" aria-label="Permalink to &quot;和 Rule 容易糊的地方&quot;">​</a></h2><p>Rule 和 Skill 都是 Markdown 说明，差别是<strong>加载策略</strong>：</p><ul><li>短、每次都不能忘 → Rule（或 AGENTS.md）</li><li>长、按场景才用 → Skill</li></ul><p>把 200 行排障手册写成 <code>alwaysApply</code> 的 Rule，等于每聊一句都带一本手册。</p><p>AGENTS.md 和 Rule 都偏常驻。差别是<strong>可移植 vs 细粒度</strong>：仓库怎么跑写 AGENTS.md（别的 Agent 也能读）；只在 Cursor 里按文件类型收紧写 Rule。同一条禁令写一份就行。</p><h2 id="怎么选" tabindex="-1">怎么选 <a class="header-anchor" href="#怎么选" aria-label="Permalink to &quot;怎么选&quot;">​</a></h2><ol><li>这个<strong>仓库</strong>的命令、目录、总禁令 → <strong>AGENTS.md</strong></li><li>改某类文件时的短约束、Cursor 专属习惯 → <strong>Rule</strong></li><li>一类任务的步骤、清单、输出模板 → <strong>Skill</strong></li><li>当前仓库 git / 脚本做不完、要接外部系统 → <strong>MCP</strong></li><li>流程要稳又要打远程 → <strong>Skill + MCP</strong>：Skill 写第几步调哪个工具</li></ol><p>优先级大致是：你当轮说的话 &gt; AGENTS.md / CLAUDE.md &gt; Rule &gt; Skill。Skill 和用户指令打架时，听用户的。</p>',27)])])}const p=l(d,[["render",i]]);export{u as __pageData,p as default};
